
export const detectIPVersion = (
  network: string,
): "IPv4" | "IPv6" | "Unknown" => {
  if (!network) return "Unknown";

  
  const ip = network.split("/")[0];

  
  if (ip.includes(":")) {
    return "IPv6";
  }

  
  if (ip.includes(".")) {
    const parts = ip.split(".");
    if (
      parts.length === 4 &&
      parts.every(
        (p) => !isNaN(Number(p)) && Number(p) >= 0 && Number(p) <= 255,
      )
    ) {
      return "IPv4";
    }
  }

  return "Unknown";
};


export const isIPv4 = (network: string): boolean => {
  return detectIPVersion(network) === "IPv4";
};


export const isIPv6 = (network: string): boolean => {
  return detectIPVersion(network) === "IPv6";
};


export const getIPStats = (networks: string[]) => {
  let ipv4 = 0;
  let ipv6 = 0;
  let unknown = 0;

  networks.forEach((network) => {
    const version = detectIPVersion(network);
    if (version === "IPv4") ipv4++;
    else if (version === "IPv6") ipv6++;
    else unknown++;
  });

  return {
    total: networks.length,
    ipv4,
    ipv6,
    unknown,
  };
};
