"use client";

import { useParams } from "next/navigation";
import { useState, useMemo } from "react";
import { motion } from "framer-motion";
import {
  ArrowLeft,
  Globe,
  MapPin,
  Copy,
  Check,
  Search,
  X,
  Wifi,
  WifiOff,
  Filter,
  Shield,
} from "lucide-react";
import Link from "next/link";
import Flag from "@/components/ui/Flag";
import { useCountryData } from "@/hooks/useData";
import Skeleton from "@/components/ui/Skeleton";
import Pagination from "@/components/ui/Pagination";
import { detectIPVersion, getIPStats } from "@/lib/ipUtils";

export default function CountryPage() {
  const params = useParams();
  const countryCode = params.countryCode as string;
  const { data, loading } = useCountryData(countryCode);
  const [currentPage, setCurrentPage] = useState(1);
  const [searchQuery, setSearchQuery] = useState("");
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
  const [filterType, setFilterType] = useState<"all" | "IPv4" | "IPv6">("all");
  const itemsPerPage = 20;

  const filteredData = useMemo(() => {
    if (!data) return [];

    let result = data;

    if (filterType !== "all") {
      result = result.filter(
        (entry) => detectIPVersion(entry.network) === filterType,
      );
    }

    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter((entry) =>
        entry.network.toLowerCase().includes(query),
      );
    }

    return result;
  }, [data, searchQuery, filterType]);

  const stats = useMemo(() => {
    if (!data) return { total: 0, ipv4: 0, ipv6: 0, unknown: 0 };
    const networks = data.map((entry) => entry.network);
    return getIPStats(networks);
  }, [data]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const currentData = filteredData.slice(startIndex, endIndex);

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const handleSearch = (value: string) => {
    setSearchQuery(value);
    setCurrentPage(1);
  };

  const clearSearch = () => {
    setSearchQuery("");
    setCurrentPage(1);
  };

  const handleFilterChange = (type: "all" | "IPv4" | "IPv6") => {
    setFilterType(type);
    setCurrentPage(1);
  };

  const copyToClipboard = async (text: string, index: number) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedIndex(index);
      setTimeout(() => setCopiedIndex(null), 2000);
    } catch (err) {
      console.error("Failed to copy:", err);
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-32 w-full" variant="card" />
        <Skeleton className="h-12 w-full" />
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {[...Array(6)].map((_, i) => (
            <Skeleton key={i} className="h-20 w-full" variant="card" />
          ))}
        </div>
      </div>
    );
  }

  if (!data || data.length === 0) {
    return (
      <div className="text-center py-16">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-[rgba(34,229,122,.08)] border border-[rgba(34,229,122,.1)] mb-4">
          <Globe size={28} className="text-[#4f6459]" />
        </div>
        <p className="text-[#93a79d] font-mono">
          No data found for {countryCode.toUpperCase()}
        </p>
        <Link
          href="/country"
          className="inline-flex items-center gap-2 text-[#22e57a] hover:text-[#5cffa5] mt-4 transition-colors font-mono text-sm"
        >
          <ArrowLeft size={14} />
          Back to countries
        </Link>
      </div>
    );
  }

  const firstEntry = data[0];
  const countryName = firstEntry.country_name;
  const continent = firstEntry.continent_code;
  const totalNetworks = data.length;
  const filteredCount = filteredData.length;

  return (
    <div className="space-y-6">
      {/* Back Button */}
      <Link
        href="/country"
        className="inline-flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors font-mono text-sm"
      >
        <ArrowLeft size={16} />
        Back to countries
      </Link>

      {/* Header Card */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-[#070b09]/80 backdrop-blur-sm border border-[rgba(34,229,122,.12)] rounded-xl p-6"
      >
        <div className="flex flex-col lg:flex-row lg:items-center gap-4">
          <div className="flex items-center gap-6">
            <div className="flex-shrink-0">
              <Flag countryCode={countryCode} size={56} variant="rounded" />
            </div>
            <div>
              <h1 className="text-2xl sm:text-3xl font-bold font-mono text-[#f2fff8]">
                {countryName}
              </h1>
              <div className="flex flex-wrap items-center gap-4 text-sm mt-1.5">
                <span className="flex items-center gap-1.5 text-[#6f8a7d]">
                  <MapPin size={15} />
                  {countryCode.toUpperCase()}
                </span>
                <span className="flex items-center gap-1.5 text-[#6f8a7d]">
                  <Globe size={15} />
                  {continent}
                </span>
                <span className="flex items-center gap-1.5 text-[#6f8a7d]">
                  <Shield size={15} />
                  {totalNetworks.toLocaleString()} networks
                </span>
                <span className="flex items-center gap-1.5 text-[#22e57a]">
                  <Wifi size={14} />
                  IPv4: {stats.ipv4}
                </span>
                <span className="flex items-center gap-1.5 text-[#5c8aff]">
                  <WifiOff size={14} />
                  IPv6: {stats.ipv6}
                </span>
                {searchQuery && (
                  <span className="text-[#22e57a] font-mono text-xs">
                    {filteredCount.toLocaleString()} filtered
                  </span>
                )}
              </div>
            </div>
          </div>
          {totalPages > 1 && !searchQuery && filterType === "all" && (
            <div className="lg:ml-auto text-xs font-mono text-[#4f6459]">
              Page {currentPage} of {totalPages}
            </div>
          )}
        </div>
      </motion.div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search
            className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#6f8a7d]"
            size={16}
          />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => handleSearch(e.target.value)}
            placeholder={`Search networks in ${countryCode.toUpperCase()}...`}
            className="w-full bg-[#070b09]/60 border border-[rgba(34,229,122,.1)] rounded-xl pl-10 pr-10 py-2.5 text-sm text-[#c6d2ca] placeholder-[#4f6459] focus:outline-none focus:border-[rgba(34,229,122,.3)] focus:ring-1 focus:ring-[rgba(34,229,122,.15)] transition-all duration-200 font-mono"
          />
          {searchQuery && (
            <button
              onClick={clearSearch}
              className="absolute right-3.5 top-1/2 -translate-y-1/2 text-[#4f6459] hover:text-[#6f8a7d] transition-colors p-1 rounded-md hover:bg-[rgba(34,229,122,.06)]"
            >
              <X size={16} />
            </button>
          )}
        </div>
        <div className="flex items-center gap-1.5 flex-shrink-0">
          <span className="text-[10px] font-mono text-[#4f6459] mr-1">
            Filter:
          </span>
          {(["all", "IPv4", "IPv6"] as const).map((type) => (
            <button
              key={type}
              onClick={() => handleFilterChange(type)}
              className={`px-2.5 py-1.5 text-[10px] font-mono font-bold rounded-md transition-all duration-200 ${
                filterType === type
                  ? type === "all"
                    ? "bg-[#22e57a] text-[#05100a]"
                    : type === "IPv4"
                      ? "bg-[#22e57a] text-[#05100a]"
                      : "bg-[#5c8aff] text-white"
                  : "bg-[#0a100d] text-[#4f6459] hover:text-[#6f8a7d] border border-[rgba(34,229,122,.06)]"
              }`}
            >
              {type === "all" ? "All" : type}
            </button>
          ))}
        </div>
      </div>

      {searchQuery && (
        <div className="text-xs font-mono text-[#6f8a7d]">
          Found {filteredCount.toLocaleString()} network
          {filteredCount !== 1 ? "s" : ""} matching "{searchQuery}"
        </div>
      )}

      {/* Networks Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
        {currentData.length > 0 ? (
          currentData.map((entry, index) => {
            const globalIndex = startIndex + index;
            const ipVersion = detectIPVersion(entry.network);
            const isIPv4 = ipVersion === "IPv4";

            return (
              <motion.div
                key={`${entry.network}-${index}`}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.02 }}
                className="group bg-[#070b09]/40 border border-[rgba(34,229,122,.06)] hover:border-[rgba(34,229,122,.15)] rounded-lg p-3.5 transition-all duration-300"
              >
                <div className="flex items-center justify-between gap-3">
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <span
                      className={`text-[10px] px-2 py-0.5 rounded font-mono font-bold flex-shrink-0 ${
                        isIPv4
                          ? "bg-[rgba(34,229,122,.08)] text-[#22e57a] border border-[rgba(34,229,122,.1)]"
                          : "bg-[rgba(92,138,255,.08)] text-[#5c8aff] border border-[rgba(92,138,255,.1)]"
                      }`}
                    >
                      {ipVersion}
                    </span>
                    <code className="text-sm font-mono text-[#7fe9ab] truncate">
                      {entry.network}
                    </code>
                  </div>
                  <div className="flex items-center gap-2 flex-shrink-0">
                    <span className="text-[10px] font-mono text-[#4f6459]">
                      {entry.country_code}
                    </span>
                    <button
                      onClick={() =>
                        copyToClipboard(entry.network, globalIndex)
                      }
                      className="p-1.5 rounded-md bg-[#0a100d] hover:bg-[rgba(34,229,122,.06)] transition-colors border border-[rgba(34,229,122,.06)] group"
                      aria-label="Copy network"
                    >
                      {copiedIndex === globalIndex ? (
                        <Check size={13} className="text-[#22e57a]" />
                      ) : (
                        <Copy
                          size={13}
                          className="text-[#4f6459] group-hover:text-[#6f8a7d]"
                        />
                      )}
                    </button>
                  </div>
                </div>
              </motion.div>
            );
          })
        ) : (
          <div className="col-span-2 text-center py-12 bg-[#070b09]/40 border border-[rgba(34,229,122,.06)] rounded-lg">
            <p className="text-[#6f8a7d] font-mono text-sm">
              {filterType !== "all"
                ? `No ${filterType} networks found`
                : `No networks found matching "${searchQuery}"`}
            </p>
            <button
              onClick={() => {
                clearSearch();
                handleFilterChange("all");
              }}
              className="mt-3 text-[#22e57a] hover:text-[#5cffa5] transition-colors font-mono text-xs"
            >
              Clear all filters
            </button>
          </div>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && filteredCount > 0 && (
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={handlePageChange}
          className="mt-6"
        />
      )}

      {/* Results count */}
      {filteredCount > 0 && (
        <div className="text-center text-xs font-mono text-[#4f6459]">
          Showing {startIndex + 1} - {Math.min(endIndex, filteredCount)} of{" "}
          {filteredCount.toLocaleString()} networks
          {searchQuery && ` (filtered from ${totalNetworks.toLocaleString()})`}
          {filterType !== "all" && ` [${filterType}]`}
        </div>
      )}
    </div>
  );
}
